import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    N = int(data[0])
    S = data[1].strip()

    left1 = [0] * (N + 1)
    for i in range(N):
        if S[i] == '1':
            left1[i + 1] = left1[i] + 1
        else:
            left1[i + 1] = 0

    right2 = [0] * (N + 1)
    for i in range(N - 1, -1, -1):
        if S[i] == '2':
            right2[i] = right2[i + 1] + 1
        else:
            right2[i] = 0

    ans = 0
    for i, ch in enumerate(S):
        if ch == '/':
            left = left1[i]
            right = right2[i + 1]
            cur = 2 * min(left, right) + 1
            if cur > ans:
                ans = cur

    print(ans)

if __name__ == "__main__":
    main()
